{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "Ensure that the Ledger feature is enabled on database that requires cryptographic proof and nonrepudiation of data integrity",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The Ledger feature is not enabled on the database. This feature ensures cryptographic proof and nonrepudiation of data integrity, which is critical for sensitive or regulated data."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "Ensure the Azure SQL Database Namespace is zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database is not configured to be zone redundant. Zone redundancy ensures high availability and resilience against zone-level failures."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n  ledger_enabled = true\n}",
  "fix_summary": "Enabled the Ledger feature to ensure cryptographic proof and nonrepudiation of data integrity. Set the database to be zone redundant to improve availability and resilience against zone-level failures."
}
